arguments.command:
curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: <TOKEN>" -d '{"query":"{ __schema { mutationType { fields(includeDeprecated: true) { name args { name type { name kind ofType { name kind } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['mutationType']['fields']:
    if f['name']=='attachmentUpdate':
        for a in f['args']:
            t=a['type']; ot=(t.get('ofType') or {})
            print(f['name'], 'arg:', a['name'], t.get('name') or t.get('kind'), ot.get('name'))
"

